mapper.select:
WITH voucher AS ( SELECT TEMP.HAPPEN_DATE, TEMP.BOOKSET_DATE, TEMP.BOOK_DATE, TEMP.BOOK_ID, TEMP.BOOKSET_ID, TEMP.OFFSET_FLAG FROM ( SELECT A.HAPPEN_DATE, A.BOOKSET_DATE, A.BOOK_DATE, A.BOOK_ID, A.BOOKSET_ID, A.OFFSET_FLAG, ROW_NUMBER() OVER( PARTITION BY A.BOOKSET_ID, A.BOOK_ID ORDER BY A.BOOK_ORDER desc ) AS RN FROM BOK_BOOKDETAIL_CURRENT A where A.BOOKSET_ID = #{booksetId} AND A.BOOK_DATE <= #{bookDate}
AND A.TABLE_ID in
#{tableId}
AND A.TRADE_ID = #{tradeId}
AND A.HAPPEN_DATE = #{happenDate}
) TEMP WHERE TEMP.RN = 1 AND TEMP.OFFSET_FLAG = #{offsetFlag} ) SELECT B.BOK_DETAIL_ID as bokDetailId, B.BASE_SUBJECT_NATURE as baseSubjectNature, B.HAPPEN_DATE as happenDate, SUM(DECODE(B.CD_FLAG,#{cdFlag},B.O_HAPPEN_AMT,B.O_HAPPEN_AMT*(-1))) AS oHappenAmt FROM BOK_BOOKDETAIL_CURRENT B INNER JOIN voucher C ON C.HAPPEN_DATE = B.HAPPEN_DATE AND C.BOOKSET_DATE = B.BOOKSET_DATE AND C.BOOK_DATE = B.BOOK_DATE AND C.BOOK_ID = B.BOOK_ID AND C.BOOKSET_ID = B.BOOKSET_ID WHERE 1=1 AND B.BASE_SUBJECT_NATURE = #{baseSubjectNature} AND B.BOK_DETAIL_ID = #{bokDetailId} GROUP BY B.BOK_DETAIL_ID, B.BASE_SUBJECT_NATURE, B.HAPPEN_DATE
